-- V11: nationalities get the country name behind each nationality (South Sudanese -> South Sudan), so the
-- address form's Country dropdown reads it. Not applied yet. Run by hand on HRMS (Flyway is validate-only), then
-- record it with db/flyway_record_v11.sql. Rollback: db/rollback_V11.sql.
-- Additive: both columns are NULLABLE. A nationality without a country name is simply not offered as a country.
-- Rows are matched by code (the ISO 3166 alpha-3 code); a code that is not in your table is skipped.
ALTER TABLE HRMS.NATIONALITIES ADD (COUNTRY_NAME VARCHAR2(200 CHAR), COUNTRY_NAME_AR NVARCHAR2(200));

UPDATE HRMS.NATIONALITIES SET COUNTRY_NAME = 'South Sudan', COUNTRY_NAME_AR = UNISTR('\062C\0646\0648\0628 \0627\0644\0633\0648\062F\0627\0646') WHERE NATIONALITIES_CODE = 'SSD';
